\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath,amssymb,amsthm}
\usepackage{microtype}
\usepackage[hidelinks]{hyperref}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{definition}[theorem]{Definition}
\newtheorem{remark}[theorem]{Remark}
\title{Canonical Binary Numeration in Negative, Irrational, and Complex Radices}
\author{Aristotle}
\date{July 22, 2026}

\begin{document}
\maketitle

\begin{abstract}
Positional notation remains meaningful far beyond positive integral radices. Every integer is shown to have a unique finite canonical expansion in base $-2$ with digits $0$ and $1$. Every natural number has a unique representation as a sum of nonconsecutive Fibonacci numbers, and the identity $\varphi^n+\varphi^{n+1}=\varphi^{n+2}$ connects this normal form to carrying in the golden-ratio radix. Finally, every Gaussian integer has a unique finite canonical expansion in base $i-1$ using the same binary alphabet. Coordinate parity forces each complex-base digit, while Gaussian-norm descent proves termination outside five explicit exceptional points. The three systems are unified by residue extraction, local normalization, well-founded descent, and canonical form.
\end{abstract}

\section{Introduction}
A conventional base-$b$ numeral is a finite sum $\sum_j d_jb^j$. When $b$ is a positive integer, division with remainder simultaneously chooses the least significant digit and produces a smaller quotient. Negative, irrational, and complex radices separate these two functions and reveal the structure beneath ordinary notation.

This paper treats base $-2$ on $\mathbb Z$, Fibonacci numeration and its relation to the golden ratio $\varphi$, and base $i-1$ on the Gaussian integers $\mathbb Z[i]$. The conclusions are exact: unique canonical expansions exist in the first and third systems, while unique nonconsecutive Fibonacci sums exist in the second. The golden-ratio carry law supplies a precise bridge to phinary notation, but does not imply the overbroad claim that nonnegative binary powers of $\varphi$ represent every integer.

\section{Positional evaluation and canonical words}
Let $R$ be a ring, $\beta\in R$, and $D\subseteq R$. A finite word $d_0,\ldots,d_k$, listed from least to most significant, has value
\[
V_\beta(d_0,\ldots,d_k)=\sum_{j=0}^k d_j\beta^j.
\]
Equivalently, $V_\beta(\varnothing)=0$ and
\[
V_\beta(d_0,d_1,\ldots)=d_0+\beta V_\beta(d_1,d_2,\ldots).
\]

\begin{definition}[Canonical binary word]
A binary word is canonical if it is empty or its most significant digit is $1$. The empty word represents zero.
\end{definition}

The leading-zero restriction is essential: appending a zero in the most significant position does not alter value.

\section{Negabinary arithmetic}
Set $\beta=-2$ and $D=\{0,1\}$. For $n\in\mathbb Z$, let $r(n)\in\{0,1\}$ be its Euclidean remainder modulo $2$, and put
\[
T(n)=\frac{r(n)-n}{2}.
\]
Then $n=r(n)+(-2)T(n)$, so $r(n)$ is the forced least significant digit.

Absolute value does not prove termination, since $T(-1)=1$. Define instead
\[
\mu(n)=\begin{cases}2n-1,&n>0,\\-2n,&n\leq0.\end{cases}
\]
This orders the integers as $0,1,-1,2,-2,\ldots$.

\begin{lemma}[Interleaving descent]
If $n\neq0$, then $\mu(T(n))<\mu(n)$.
\end{lemma}
\begin{proof}
Split according to sign and parity. For $n=2k>0$, one has $T(n)=-k$ and $2k<4k-1$. For $n=2k+1>0$, one has $T(n)=-k$ and $2k<4k+1$. Substitution of $n=-2k$ and $n=-(2k+1)$ gives the two negative cases directly. Each inequality is strict.
\end{proof}

\begin{theorem}[Existence of canonical negabinary expansions]
Every integer is the value of a finite canonical base-$-2$ word with digits $0$ and $1$.
\end{theorem}
\begin{proof}
Induct on $\mu(n)$. Zero uses the empty word. For nonzero $n$, the lemma permits induction on $T(n)$. Prefix the resulting quotient word by $r(n)$ at the least significant end and use $n=r(n)-2T(n)$. If the quotient is zero, nonzero $n$ forces $r(n)=1$; otherwise canonicality is inherited from the quotient word.
\end{proof}

\begin{lemma}[Parity recovers the first digit]
For a digit $d\in\{0,1\}$ and a tail $w$,
\[
V_{-2}(d,w)\bmod2=d.
\]
\end{lemma}
\begin{proof}
Every term belonging to the tail is divisible by $2$.
\end{proof}

\begin{lemma}[Canonical zero]
A canonical base-$-2$ word has value zero if and only if it is empty.
\end{lemma}
\begin{proof}
A nonempty zero word must begin with $0$ by parity. Removing that digit and dividing by $-2$ gives a shorter canonical zero word. Iteration would end with the one-digit canonical word $1$, a contradiction.
\end{proof}

\begin{theorem}[Unique negabinary representation]
Every integer has exactly one finite canonical base-$-2$ expansion with digits $0$ and $1$.
\end{theorem}
\begin{proof}
Existence was established above. For equal-valued canonical words, the canonical-zero lemma handles empty cases. Parity forces equal first digits. Subtract that digit and divide by $-2$ to equate the tails; induction proves equality.
\end{proof}

For example,
\[
110111_{(-2)}=(-2)^5+(-2)^4+(-2)^2+(-2)+1=-13.
\]
Digit extraction takes $O(\log(|n|+1))$ iterations and is linear in the output length under unit-cost arithmetic.

\section{Fibonacci numeration and the golden ratio}
Let $F_0=0$, $F_1=1$, and $F_{k+2}=F_{k+1}+F_k$.

\begin{definition}[Admissible Fibonacci representation]
An admissible representation of $n\in\mathbb N$ is a finite set $S\subseteq\{2,3,\ldots\}$ with no consecutive members and
\[
n=\sum_{j\in S}F_j.
\]
\end{definition}

\begin{theorem}[Zeckendorf representation]
Every natural number has exactly one admissible Fibonacci representation.
\end{theorem}
\begin{proof}
For existence, repeatedly choose the largest Fibonacci number not exceeding the remainder. If $F_k$ is chosen, then the new remainder is smaller than $F_{k-1}$, since otherwise $F_{k+1}=F_k+F_{k-1}$ would also fit. Hence adjacent indices are never selected, and the decreasing remainder proves termination.

For uniqueness, the sum of all mutually nonadjacent permitted terms below $F_k$ is smaller than $F_k$. Thus equal admissible sums must have the same largest term. Remove it and repeat.
\end{proof}

Thus
\[
100=89+8+3=F_{11}+F_6+F_4.
\]

Let $\varphi=(1+\sqrt5)/2$.
\begin{theorem}[Golden-ratio carry]
For every $n\in\mathbb N$,
\[
\varphi^n+\varphi^{n+1}=\varphi^{n+2}.
\]
\end{theorem}
\begin{proof}
Multiply $\varphi^2=\varphi+1$ by $\varphi^n$.
\end{proof}

This is the positional rewrite $011\leftrightarrow100$, exactly paralleling the Fibonacci recurrence. Its scope must nevertheless be stated carefully. Every finite sum of nonnegative powers of $\varphi$ reduces to $A+B\varphi$ with $A,B\in\mathbb Z$. Binary nonnegative coefficients do not generally provide the cancellation required to make $B=0$ for arbitrary integer targets. General integral phinary expansions need negative powers or a specified alternative endpoint convention. What is established here is unique Fibonacci numeration together with the exact algebraic carry law.

The greedy algorithm requires $O(\log n)$ Fibonacci values because Fibonacci growth is exponential.

\section{Binary notation in the Gaussian plane}
The Gaussian integers are $\mathbb Z[i]=\{x+yi:x,y\in\mathbb Z\}$. Set $\beta=i-1$, use digits $\{0,1\}$, and define the norm $N(x+yi)=x^2+y^2$. Multiplication by $\beta$ satisfies
\[
(i-1)(u+vi)=(-u-v)+(u-v)i.
\]
Its output has even coordinate sum.

For $z=x+yi$, choose $d(z)\in\{0,1\}$ by
\[
d(z)\equiv x+y\pmod2,
\]
and define
\[
T(z)=\frac{z-d(z)}{i-1}
=\frac{y-(x-d(z))}{2}-\frac{(x-d(z))+y}{2}i.
\]
Both coordinates are integral.

\begin{lemma}[Reconstruction]
For every Gaussian integer $z$,
\[
z=d(z)+(i-1)T(z).
\]
\end{lemma}
\begin{proof}
Substitute the coordinate expression for $T(z)$ into the multiplication formula. The coordinates simplify to $x$ and $y$.
\end{proof}

\begin{lemma}[Complex parity extraction]
If a binary word begins with $d$ and has value $x+yi$ in base $i-1$, then $x+y\equiv d\pmod2$.
\end{lemma}
\begin{proof}
The tail is multiplied by $i-1$ and therefore contributes an even coordinate sum.
\end{proof}

A calculation gives
\[
2N(T(z))=(x-d(z))^2+y^2.
\]
Norm descent is not unconditional: for $z=i$, one obtains $T(i)=1$, and both norms are $1$.

\begin{lemma}[Descent outside five points]
If $z\neq0$, then either
\[
z\in\{i,-i,-1,-2+i,-2-i\},
\]
or $N(T(z))<N(z)$.
\end{lemma}
\begin{proof}
If descent fails, then
\[
(x-d)^2+y^2\geq2(x^2+y^2),\qquad d\in\{0,1\}.
\]
Quadratic estimates force $-2\leq x\leq2$ and $-1\leq y\leq1$. Checking this finite rectangle using the parity rule leaves precisely the five stated nonzero points.
\end{proof}

Least-significant-first canonical words for the exceptions are
\[
\begin{array}{c|c}
i&(1,1)\\
-i&(1,1,1)\\
-1&(1,0,1,1,1)\\
-2+i&(1,1,1,1,1)\\
-2-i&(1,1,0,1,0,1,1,1).
\end{array}
\]

\begin{theorem}[Existence in base $i-1$]
Every Gaussian integer has a finite canonical base-$(i-1)$ expansion with digits $0$ and $1$.
\end{theorem}
\begin{proof}
Induct on $N(z)$. Zero uses the empty word, and the five exceptional points use the displayed words. Every other nonzero point has a smaller-norm successor. Represent the successor inductively, prefix $d(z)$, and apply reconstruction. Canonicality is inherited unless the successor is zero, in which case nonzero $z$ forces $d(z)=1$.
\end{proof}

\begin{lemma}[Complex canonical zero]
A canonical base-$(i-1)$ binary word representing zero is empty.
\end{lemma}
\begin{proof}
Complex parity extraction forces the first digit of a nonempty zero word to be $0$. Cancel it and divide by $i-1$ to obtain a shorter canonical zero word, eventually contradicting the final leading $1$.
\end{proof}

\begin{theorem}[Unique Gaussian binary representation]
Every Gaussian integer has exactly one finite canonical base-$(i-1)$ expansion using digits $0$ and $1$.
\end{theorem}
\begin{proof}
Existence is above. Equal-valued canonical words have equal first digits by coordinate-sum parity. Cancellation and division by the nonzero radix equate their tails. The canonical-zero lemma handles empty cases, and induction completes the proof.
\end{proof}

For example, $11_{(i-1)}=1+(i-1)=i$. The conversion algorithm consists of parity, additions, subtractions, and division by two; the five terminal exceptions form a constant lookup table.

\section{Unified interpretation and applications}
All three systems use local normalization. Residues choose digits in bases $-2$ and $i-1$, while the Fibonacci recurrence chooses legal carries. A quotient or rewrite advances computation. Termination depends on geometry suited to the radix: an interleaving measure on $\mathbb Z$, greedy remainder descent on $\mathbb N$, or Gaussian norm outside a finite exceptional region. Canonical restrictions then convert existence into uniqueness.

Negabinary notation stores signed integers without a sign symbol. Fibonacci forms support recurrence-based integer coding and localized normalization. Complex binary notation serializes a planar lattice point as one bit string and suggests applications in lattice addressing and Gaussian arithmetic. Numeral systems may therefore be compared not only by length but also by carry complexity, boundary behavior, and geometric compatibility.

\section{Limitations and future directions}
Leading zeroes cannot be admitted if uniqueness is desired. Termination measures must be proved rather than guessed: absolute value fails at $-1$ in negabinary, and Gaussian norm fails at $i$. The phinary bridge also requires care: unique nonconsecutive Fibonacci sums and the golden-ratio carry do not alone constitute a canonical theorem for arbitrary integers using only nonnegative powers.

Further work includes classifying norm-two quadratic radices with binary canonical expansions, constructing a terminating and confluent transducer between Zeckendorf and phinary endpoint conventions, extending negative-base extraction to Euclidean domains, and studying the expected normalization cost of random numerals through finite carry automata.

\section{Conclusion}
Base $-2$ gives a complete unique signless binary notation for $\mathbb Z$. Nonconsecutive Fibonacci sums give a complete unique notation for $\mathbb N$, with the golden-ratio identity explaining the associated local carry. Base $i-1$ gives a complete unique signless binary notation for $\mathbb Z[i]$, with five exceptional points marking the precise boundary of norm descent. In every case, the decisive ingredients are digit extraction, termination, and canonical form.

\end{document}

